package com.videokit.spike.e4;
import java.io.*;import java.net.*;import java.nio.file.*;import java.nio.charset.*;import java.util.*;import java.util.concurrent.atomic.*;
public final class R1Check {
 static String service(InputStream in)throws Exception{byte[] h=in.readNBytes(4);ICheck.need(h.length==4,"fixture request length");int n=Integer.parseInt(new String(h,StandardCharsets.US_ASCII),16);ICheck.need(n<=2048,"fixture service bound");return new String(in.readNBytes(n),StandardCharsets.US_ASCII);}
 public static void main(String[] args)throws Exception{Path p=Paths.get(args[0]);Files.createDirectories(p);AtomicReference<E13JSocket> ref=new AtomicReference<>();AtomicLong atFailure=new AtomicLong(-1);AtomicReference<Throwable> peerFailure=new AtomicReference<>();ServerSocket server=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"));server.setSoTimeout(1500);
  Thread peer=new Thread(()->{try(Socket s=server.accept()){s.setSoTimeout(1500);InputStream in=s.getInputStream();OutputStream out=s.getOutputStream();ICheck.need(service(in).equals("host:transport:HA1Q6WXR"),"same transport");out.write("OKAY".getBytes(StandardCharsets.US_ASCII));out.flush();ICheck.need(service(in).equals("shell,v2,raw:"+E13JIdentity.INVENTORY),"fixed shell");out.write("OKAY".getBytes(StandardCharsets.US_ASCII));out.flush();ICheck.need(Arrays.equals(in.readNBytes(5),new byte[]{4,0,0,0,0}),"close stdin control");out.write(new byte[]{1,1,0,0,0,88});out.flush();long end=System.nanoTime()+3_000_000_000L;while(!ref.get().archive.failed&&System.nanoTime()<end)Thread.sleep(2);ICheck.need(ref.get().archive.failed,"raw writer fault reached");out.write(new byte[]{7,0,0,0,0});out.write(new byte[512]);out.flush();}catch(Throwable t){peerFailure.set(t);}finally{try{server.close();}catch(IOException ignored){}}},"LOCAL_R1_LATE_BYTES_PEER");peer.setDaemon(false);peer.start();
  E13JArchive.IO io=file->{OutputStream actual=Files.newOutputStream(file,StandardOpenOption.CREATE_NEW);if(!file.getFileName().toString().equals("original.wire"))return actual;return new FilterOutputStream(actual){public void write(byte[] b,int off,int n)throws IOException{E13JSocket o=ref.get();if(o!=null&&o.incomingWire>8){atFailure.compareAndSet(-1,o.chargedWire);throw new IOException("CONTROLLED_RAW_WRITE_FAILURE_BEFORE_LATE_RX");}out.write(b,off,n);}};};
  E13JSocket original=new E13JSocket(p,E13JIdentity.INVENTORY,"127.0.0.1",server.getLocalPort(),point->{},io);ref.set(original);boolean rejected=false;try{original.run(E13JSocket.QUALIFICATION);}catch(IOException expected){rejected=true;}finally{peer.join();original.reader.join();original.keeper.join();}
  ICheck.need(rejected&&peerFailure.get()==null&&original.physicalReturned&&original.archive.failed&&!original.archive.auditFailed,"same failed owner actually returned and audit preserved");ICheck.need(atFailure.get()>=0&&original.chargedWire>atFailure.get(),"actual application bytes arrived after raw writer failure");String audit=Files.readString(p.resolve("facts.txt"));ICheck.need(audit.contains("phase=T cw="+original.chargedWire+" ")&&audit.contains("in="+original.incomingWire+" ")&&audit.contains("qualification=FAILED")&&audit.contains("readerBody=true"),"production terminal audit contains all late consumed bytes after raw write failure");ICheck.need(Files.size(p.resolve("facts.txt"))<=1024&&original.chargedWire<=70656,"unchanged metadata and application budgets");System.out.println("PASS AUDIT_AFTER_RAW_FAILURE atFailure="+atFailure+" finalCharged="+original.chargedWire+" actualRx="+original.incomingWire+" terminalProductionAuditMatches=true noHarnessFacts=true socketCloseOriginalReturned=true");
 }
}
